    $c.util.getComponent('ipt_cfiCd').setValue("");
    $c.util.getComponent('ipt_cfiCd').setValue(($c.util.getComponent("ipt_cfiCdCategory").getValue() || '') + $('input[name=group]:checked').val() + ($c.util.getComponent("slc_attr01").getValue() || '') + ($c.util.getComponent("slc_attr02").getValue() || '') + ($c.util.getComponent("slc_attr03").getValue() || '') + ($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdGroup').setValue($('input[name=group]:checked').val());
